{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.MoM_demand_plan_summary_review as WITH month_dim AS ( SELECT DATE \'2026-04-01\' AS month_start, \'Apr-26\' AS month_label, 1 AS month_order UNION ALL SELECT DATE \'2026-05-01\', \'May-26\', 2 UNION ALL SELECT DATE \'2026-06-01\', \'Jun-26\', 3 UNION ALL SELECT DATE \'2026-07-01\', \'Jul-26\', 4 UNION ALL SELECT DATE \'2026-08-01\', \'Aug-26\', 5 UNION ALL SELECT DATE \'2026-09-01\', \'Sep-26\', 6 UNION ALL SELECT DATE \'2026-10-01\', \'Oct-26\', 7 UNION ALL SELECT DATE \'2026-11-01\', \'Nov-26\', 8 UNION ALL SELECT DATE \'2026-12-01\', \'Dec-26\', 9 UNION ALL SELECT DATE \'2027-01-01\', \'Jan-27\', 10 UNION ALL SELECT DATE \'2027-02-01\', \'Feb-27\', 11 ), meta_map AS ( SELECT UPPER( CASE WHEN UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2) ELSE REPLACE(SKU_GROUP, \' \', \'\') END ELSE SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) END ) AS sku_group_clean, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ))) AS l1_category, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ))) AS category, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END), MIN(a.meta1), \'na\' ))) AS meta1, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END), MIN(a.meta2), \'na\' ))) AS meta2, LOWER(TRIM(COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END), MIN(a.meta3), \'na\' ))) AS meta3, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), closing_stock AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'1. Closing Stock\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_closing_stock UNPIVOT ( value FOR month_raw IN ( April, May, June, July, August, September, October, November, December, January, February ) ) ), online_sales AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'3. Online Sales\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_online_sales UNPIVOT ( value FOR month_raw IN ( Apr, May, June, July, Aug, Sept, Oct, Nov, Dec, Jan, Feb ) ) ), offline_sales AS ( SELECT LOWER(TRIM(l_1)) AS l1, LOWER(TRIM(category)) AS cat, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(l_1)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(meta_3, \'na\'))) END AS meta3, CASE UPPER(month_raw) WHEN \'APRIL\' THEN \'Apr-26\' WHEN \'APR\' THEN \'Apr-26\' WHEN \'MAY\' THEN \'May-26\' WHEN \'JUNE\' THEN \'Jun-26\' WHEN \'JUN\' THEN \'Jun-26\' WHEN \'JULY\' THEN \'Jul-26\' WHEN \'JUL\' THEN \'Jul-26\' WHEN \'AUGUST\' THEN \'Aug-26\' WHEN \'AUG\' THEN \'Aug-26\' WHEN \'SEPTEMBER\' THEN \'Sep-26\' WHEN \'SEPT\' THEN \'Sep-26\' WHEN \'SEP\' THEN \'Sep-26\' WHEN \'OCTOBER\' THEN \'Oct-26\' WHEN \'OCT\' THEN \'Oct-26\' WHEN \'NOVEMBER\' THEN \'Nov-26\' WHEN \'NOV\' THEN \'Nov-26\' WHEN \'DECEMBER\' THEN \'Dec-26\' WHEN \'DEC\' THEN \'Dec-26\' WHEN \'JANUARY\' THEN \'Jan-27\' WHEN \'JAN\' THEN \'Jan-27\' WHEN \'FEBRUARY\' THEN \'Feb-27\' WHEN \'FEB\' THEN \'Feb-27\' END AS month, \'5. Offline Sales\' AS metrics, COALESCE(TRY_TO_NUMBER(REPLACE(value::STRING, \',\', \'\')), 0) AS value FROM snitch_db.maplemonk.demand_requirement_r_offline_sales UNPIVOT ( value FOR month_raw IN ( Apr, May, June, July, Aug, Sept, Oct, Nov, Dec, Jan, Feb ) ) ), actual_closing_stock_candidates_2 AS ( SELECT LOWER(TRIM(mm.l1_category)) AS l1, LOWER(TRIM(mm.category)) AS cat, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta3, \'na\'))) END AS meta3, md.month_label AS month, c.date::DATE AS snapshot_date, SUM( COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_available::STRING, \',\', \'\')), 0) + COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_offline_available::STRING, \',\', \'\')), 0) + COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_jit::STRING, \',\', \'\')), 0) ) AS value FROM snitch_db.maplemonk.cogs_daily_snapshot c JOIN month_dim md ON c.date::DATE IN ( LAST_DAY(md.month_start)::DATE, DATEADD(DAY, 1, LAST_DAY(md.month_start))::DATE ) LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( CASE WHEN UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 2) ELSE REPLACE(c.sku_group, \' \', \'\') END ELSE SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1) END ) GROUP BY 1,2,3,4,5,6,7 ), latest_snapshot_by_month AS ( SELECT md.month_start, MAX(c.date::DATE) AS latest_snapshot_date FROM snitch_db.maplemonk.cogs_daily_snapshot c JOIN month_dim md ON c.date::DATE >= md.month_start AND c.date::DATE < DATEADD(MONTH, 1, md.month_start) GROUP BY 1 ), actual_closing_stock_candidates AS ( SELECT LOWER(TRIM(mm.l1_category)) AS l1, LOWER(TRIM(mm.category)) AS cat, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta3, \'na\'))) END AS meta3, md.month_label AS month, c.date::DATE AS snapshot_date, SUM( COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_available::STRING, \',\', \'\')), 0) + COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_offline_available::STRING, \',\', \'\')), 0) + COALESCE(TRY_TO_NUMBER(REPLACE(c.qty_jit::STRING, \',\', \'\')), 0) ) AS value FROM snitch_db.maplemonk.cogs_daily_snapshot c JOIN month_dim md ON c.date::DATE >= md.month_start AND c.date::DATE < DATEADD(MONTH, 1, md.month_start) LEFT JOIN latest_snapshot_by_month lsm ON lsm.month_start = md.month_start LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( CASE WHEN UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(c.sku_group, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 2) ELSE REPLACE(c.sku_group, \' \', \'\') END ELSE SPLIT_PART(REPLACE(c.sku_group, \' \', \'\'), \'-\', 1) END ) WHERE ( md.month_start = DATE_TRUNC(\'MONTH\', CURRENT_DATE())::DATE AND c.date::DATE = lsm.latest_snapshot_date ) OR ( md.month_start < DATE_TRUNC(\'MONTH\', CURRENT_DATE())::DATE AND c.date::DATE IN ( LAST_DAY(md.month_start)::DATE, DATEADD(DAY, 1, LAST_DAY(md.month_start))::DATE ) ) GROUP BY 1,2,3,4,5,6,7 ), actual_closing_stock AS ( SELECT l1, cat, meta1, meta2, meta3, month, \'2. Actual Closing Stock\' AS metrics, value FROM actual_closing_stock_candidates QUALIFY ROW_NUMBER() OVER ( PARTITION BY l1, cat, meta1, meta2, meta3, month ORDER BY value DESC, snapshot_date DESC ) = 1 ), putaway_clean AS ( SELECT p.*, TRIM( REVERSE( SUBSTRING( REVERSE(p.\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(p.\"Item Type skuCode\")) + 1, LEN(p.\"Item Type skuCode\") ) ) ) AS extracted_sku_group FROM snitch_db.maplemonk.putaway_tracking p ), actual_sales_base AS ( SELECT LOWER(TRIM(mm.l1_category)) AS l1, LOWER(TRIM(mm.category)) AS cat, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta1, \'na\'))) END AS meta1, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta2, \'na\'))) END AS meta2, CASE WHEN UPPER(TRIM(mm.l1_category)) = \'LUXE\' THEN \'na\' ELSE LOWER(TRIM(COALESCE(mm.meta3, \'na\'))) END AS meta3, md.month_label AS month, CASE WHEN h.type IN (\'Shopify\', \'Marketplace\') THEN \'4. Actual Online Sales\' WHEN h.type = \'Store\' THEN \'6. Actual Offline Sales\' END AS metrics, SUM(COALESCE(TRY_TO_NUMBER(REPLACE(h.gross_quantity::STRING, \',\', \'\')), 0)) AS value FROM snitch_db.maplemonk.horizontal_sales_categories h JOIN month_dim md ON h.date::DATE >= md.month_start AND h.date::DATE < DATEADD(MONTH, 1, md.month_start) LEFT JOIN meta_map mm ON mm.sku_group_clean = UPPER( CASE WHEN UPPER(REPLACE(h.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(h.sku_group, \' \', \'\')) LIKE \'4C-%\' THEN CASE WHEN SPLIT_PART(REPLACE(h.sku_group, \' \', \'\'), \'-\', 2) <> \'\' THEN SPLIT_PART(REPLACE(h.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(h.sku_group, \' \', \'\'), \'-\', 2) ELSE REPLACE(h.sku_group, \' \', \'\') END ELSE SPLIT_PART(REPLACE(h.sku_group, \' \', \'\'), \'-\', 1) END ) WHERE h.type IN (\'Shopify\', \'Marketplace\', \'Store\') GROUP BY 1,2,3,4,5,6,7 ), final AS ( SELECT * FROM closing_stock UNION ALL SELECT * FROM actual_closing_stock UNION ALL SELECT * FROM online_sales UNION ALL SELECT * FROM actual_sales_base WHERE metrics = \'6. Actual Online Sales\' UNION ALL SELECT * FROM offline_sales UNION ALL SELECT * FROM actual_sales_base WHERE metrics = \'8. Actual Offline Sales\' ) SELECT l1 AS \"L1\", cat AS \"Cat\", meta1 AS \"Meta 1\", meta2 AS \"Meta 2\", meta3 AS \"Meta 3\", month AS \"Month\", CASE WHEN \"Month\" = \'Apr-26\' THEN 1 WHEN \"Month\" = \'May-26\' THEN 2 WHEN \"Month\" = \'Jun-26\' THEN 3 WHEN \"Month\" = \'Jul-26\' THEN 4 WHEN \"Month\" = \'Aug-26\' THEN 5 WHEN \"Month\" = \'Sep-26\' THEN 6 WHEN \"Month\" = \'Oct-26\' THEN 7 WHEN \"Month\" = \'Nov-26\' THEN 8 WHEN \"Month\" = \'Dec-26\' THEN 9 WHEN \"Month\" = \'Jan-27\' THEN 10 WHEN \"Month\" = \'Feb-27\' THEN 11 ELSE 99 END monthv1, metrics AS \"Metrics\", SUM(COALESCE(value, 0)) AS \"Value\" FROM final WHERE month IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8 ORDER BY \"L1\", \"Cat\", \"Meta 1\", \"Meta 2\", \"Meta 3\", CASE \"Month\" WHEN \'Apr-26\' THEN 1 WHEN \'May-26\' THEN 2 WHEN \'Jun-26\' THEN 3 WHEN \'Jul-26\' THEN 4 WHEN \'Aug-26\' THEN 5 WHEN \'Sep-26\' THEN 6 WHEN \'Oct-26\' THEN 7 WHEN \'Nov-26\' THEN 8 WHEN \'Dec-26\' THEN 9 WHEN \'Jan-27\' THEN 10 WHEN \'Feb-27\' THEN 11 ELSE 99 END, \"Metrics\" ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

